"""Explanations for the Forge (QM formulas by heart, game/content/qm/forge.json): for every formula what it says (meaning),
a plain-language explanation of every rebuild step (explain, same length as steps) and where it is in the script (where,
with the guided-reading card). Adds the fields in place; rerunnable. Run: python3 explain.py"""
import json, os
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../../../game/content/qm/forge.json')

