x = json.load(open(P))
for it in x['items']:
    e = X[it['id']]
    assert len(e['explain']) == len(it['steps']), (it['id'], len(e['explain']), len(it['steps']))
    it['meaning'], it['explain'], it['where'] = e['meaning'], e['explain'], e['where']
with open(P, 'w') as f: json.dump(x, f, ensure_ascii=False, indent=1)
print('explained', len(x['items']), 'Forge formulas')
